// SPDX-License-Identifier: MIT
// Wardens' Accord (Prismheart campaign), plain C++17 for the Unreal binding. A port of
// tools/minigames/wardens_accord.py (prism-shard-dev), which stays the rules authority. Seeding is CPython-compatible
// (DaedalusPyRandomCore.h, "wardens_accord:<seed>:<difficulty>"), so the same seed is the same altar and spirits.
// Byte parity goes through engines/unreal/core-test/wardens_accord_parity.txt (wardens_accord_core_test.cpp),
// generated by tools/minigames/wardens_accord_parity.py.
#pragma once
#include "DaedalusPyRandomCore.h"
#include <algorithm>
#include <cstdint>
#include <string>
#include <utility>
#include <vector>

namespace daedalus { namespace wardens {

inline const char* GameId() { return "wardens_accord"; }
inline const char* Title() { return "Wardens' Accord"; }

constexpr int HueCount = 5;
inline const char* HueName(int H)
{
	static const char* Names[HueCount] = { "ember", "tide", "verdant", "gale", "umbra" };
	return H >= 0 && H < HueCount ? Names[H] : "none";
}
constexpr int NameCount = 7;
inline const char* SpiritName(int I)
{
	static const char* Names[NameCount] = { "Cinder Wisp", "Mere Sprite", "Thornkin", "Sky Lark Spirit", "Hollow Moth", "Glass Heron", "Lantern Newt" };
	return I >= 0 && I < NameCount ? Names[I] : "";
}

struct Difficulty { const char* Name; int Hues; int Rounds; int Target; int Spirits; };
inline const Difficulty* Difficulties()
{
	static const Difficulty Table[] = { { "easy", 3, 16, 40, 4 }, { "normal", 4, 14, 50, 4 }, { "hard", 5, 12, 55, 3 } };
	return Table;
}
constexpr int DifficultyCount = 3;
inline const Difficulty* FindDifficulty(const std::string& Name)
{
	for (int I = 0; I < DifficultyCount; ++I) if (Name == Difficulties()[I].Name) return &Difficulties()[I];
	return nullptr;
}

/** One spirit on the altar. Cost keys are kept in CPython dict (insertion) order: the order sample() returned them. */
struct Spirit
{
	int Name = 0;                                  // index into SpiritName
	std::vector<std::pair<int, int>> Cost;         // (hue, count) in insertion order
	int Value = 0;
	int CostOf(int Hue) const { for (const auto& P : Cost) if (P.first == Hue) return P.second; return 0; }
};

struct Game
{
	const Difficulty* Diff = nullptr;
	int Rounds = 0;
	int Pouch[HueCount] = { 0, 0, 0, 0, 0 };
	std::vector<int> Offer;          // three hues
	std::vector<Spirit> Spirits;
	std::vector<int> Summoned;       // spirit name indices, in order
	int Score = 0; bool Over = false, Won = false;
	pyrandom::PyRandom Rng;

	int Hues() const { return Diff ? Diff->Hues : 0; }

	int RandInt(int A, int B) { return A + static_cast<int>(Rng.Below(static_cast<std::uint32_t>(B - A + 1))); }

	std::vector<int> MakeOffer()
	{
		std::vector<int> O;
		for (int I = 0; I < 3; ++I) O.push_back(static_cast<int>(Rng.ChoiceIndex(static_cast<size_t>(Hues()))));
		return O;
	}

	Spirit MakeSpirit()
	{
		const int Size = RandInt(2, 4);
		const int K = RandInt(1, 2);
		const std::vector<std::size_t> Picked = Rng.SampleIndices(static_cast<size_t>(Hues()), static_cast<size_t>(K));
		Spirit S;
		for (std::size_t H : Picked) S.Cost.push_back({ static_cast<int>(H), 0 });
		// keys = sorted(cost): alphabetical hue names; increments round-robin over that order
		std::vector<int> Keys; for (const auto& P : S.Cost) Keys.push_back(P.first);
		std::sort(Keys.begin(), Keys.end(), [](int A, int B) { return std::string(HueName(A)) < std::string(HueName(B)); });
		for (int I = 0; I < Size; ++I)
		{
			const int Hue = Keys[static_cast<size_t>(I) % Keys.size()];
			for (auto& P : S.Cost) if (P.first == Hue) ++P.second;
		}
		S.Value = Size * 5 + (Keys.size() == 2 ? 5 : 0);
		S.Name = static_cast<int>(Rng.ChoiceIndex(static_cast<size_t>(NameCount)));
		return S;
	}

	bool Affordable(int I) const
	{
		if (I < 0 || I >= static_cast<int>(Spirits.size())) return false;
		for (const auto& P : Spirits[static_cast<size_t>(I)].Cost) if (Pouch[P.first] < P.second) return false;
		return true;
	}

	bool Start(std::uint32_t Seed, const std::string& DifficultyName)
	{
		Diff = FindDifficulty(DifficultyName);
		if (!Diff) return false;
		Rng.Seed(std::string(GameId()) + ":" + std::to_string(Seed) + ":" + DifficultyName);
		Score = 0; Over = Won = false;
		Rounds = Diff->Rounds;
		for (int& P : Pouch) P = 0;
		Summoned.clear();
		Spirits.clear(); for (int I = 0; I < Diff->Spirits; ++I) Spirits.push_back(MakeSpirit());
		Offer = MakeOffer();
		return true;
	}

	enum class Act : int { Ok = 0, GameOver, BadIndex, NotAffordable };

	void Settle()
	{
		if (Score >= Diff->Target) { Over = true; Won = true; return; }
		if (Rounds <= 0) { bool Any = false; for (int J = 0; J < static_cast<int>(Spirits.size()); ++J) Any = Any || Affordable(J); if (!Any) { Over = true; Won = false; } }
	}

	Act Take(int I, int& Gained)
	{
		Gained = 0;
		if (Over) return Act::GameOver;
		if (I < 0 || I >= 3) return Act::BadIndex;
		++Pouch[Offer[static_cast<size_t>(I)]];
		--Rounds;
		Offer = MakeOffer();
		Settle();
		return Act::Ok;
	}

	Act Summon(int I, int& Gained)
	{
		Gained = 0;
		if (Over) return Act::GameOver;
		if (I < 0 || I >= static_cast<int>(Spirits.size())) return Act::BadIndex;
		if (!Affordable(I)) return Act::NotAffordable;
		const Spirit S = Spirits[static_cast<size_t>(I)];
		for (const auto& P : S.Cost) Pouch[P.first] -= P.second;
		Gained = S.Value; Score += Gained;
		Summoned.push_back(S.Name);
		Spirits[static_cast<size_t>(I)] = MakeSpirit();
		Settle();
		return Act::Ok;
	}

	/** wardens_accord.Game.demo_action: ("summon", best affordable by (value, -i)) else ("take", k) by fewest missing. */
	std::pair<bool, int> DemoAction() const   // (true = summon, index)
	{
		int Best = -1;
		for (int I = 0; I < static_cast<int>(Spirits.size()); ++I)
			if (Affordable(I) && (Best < 0 || Spirits[static_cast<size_t>(I)].Value > Spirits[static_cast<size_t>(Best)].Value)) Best = I;
		if (Best >= 0) return { true, Best };
		auto Missing = [&](int I, int Extra) { int M = 0; for (const auto& P : Spirits[static_cast<size_t>(I)].Cost) M += std::max(0, P.second - Pouch[P.first] - (P.first == Extra ? 1 : 0)); return M; };
		int BestK = 0, BestMiss = 1 << 30;
		for (int K = 0; K < 3; ++K)
		{
			int Mn = 1 << 30; for (int I = 0; I < static_cast<int>(Spirits.size()); ++I) Mn = std::min(Mn, Missing(I, Offer[static_cast<size_t>(K)]));
			if (Mn < BestMiss) { BestMiss = Mn; BestK = K; }
		}
		return { false, BestK };
	}

	std::string PouchString() const { std::string S; for (int H = 0; H < Hues(); ++H) { if (H) S.push_back(','); S += std::to_string(Pouch[H]); } return S; }
	std::string OfferString() const { std::string S; for (size_t I = 0; I < Offer.size(); ++I) { if (I) S.push_back(','); S += HueName(Offer[I]); } return S; }
	std::string SpiritsString() const
	{
		std::string S;
		for (size_t I = 0; I < Spirits.size(); ++I)
		{
			if (I) S.push_back(';');
			S += std::to_string(Spirits[I].Name); S.push_back(':');
			for (size_t J = 0; J < Spirits[I].Cost.size(); ++J) { if (J) S.push_back('+'); S += HueName(Spirits[I].Cost[J].first); S.push_back('='); S += std::to_string(Spirits[I].Cost[J].second); }
			S.push_back(':'); S += std::to_string(Spirits[I].Value);
		}
		return S;
	}
};

} } // namespace daedalus::wardens
